// Measures MajSimai through the C++ wrapper generated by tools/MajSimai.CppGen on the corpus given on standard input.
// See BenchmarkCommon.h for the arguments and tools/benchmark-native.py for how it is run.
//
// Modes:
//   view   SimaiParser::ParseAsView: parses the file and reads the result in native memory through views.
//   model  SimaiParser::Parse: parses the file and copies the result into std::string and std::vector.

#include "BenchmarkCommon.h"

#include "MajSimai/MajSimai.h"

#include <cstdint>
#include <string_view>

namespace
{
    /// Parses one file with ParseAsView and counts its notes through the views.
    /// @param file The file to parse.
    /// @param notes The note count to add to.
    /// @return 0 when the file was parsed, 1 when MajSimai rejected it.
    int ParseAsView(const BenchFile* file, uint64_t* notes)
    {
        try
        {
            const auto parsed = MajSimai::SimaiParser::ParseAsView(std::string_view(file->data, file->length));
            const auto view = parsed.GetFile();
            for (const auto chart : view.GetCharts())
            {
                for (const auto timing : chart.GetNoteTimings())
                {
                    *notes += timing.GetNotes().Size();
                }
            }
            return 0;
        }
        catch (const MajSimai::SimaiParseException&)
        {
            return 1;
        }
    }

    /// Parses one file with Parse, which copies it into owned data, and counts its notes.
    /// @param file The file to parse.
    /// @param notes The note count to add to.
    /// @return 0 when the file was parsed, 1 when MajSimai rejected it.
    int ParseAsModel(const BenchFile* file, uint64_t* notes)
    {
        try
        {
            const auto parsed = MajSimai::SimaiParser::Parse(std::string_view(file->data, file->length));
            for (const auto& chart : parsed.charts)
            {
                for (const auto& timing : chart.noteTimings)
                {
                    *notes += timing.notes.size();
                }
            }
            return 0;
        }
        catch (const MajSimai::SimaiParseException&)
        {
            return 1;
        }
    }
}

/// Runs the benchmark in the mode given by the fifth argument (view by default).
int BENCH_MAIN(int argc, bench_char** argv)
{
    if (argc <= 4 || BENCH_STRCMP(argv[4], BENCH_TEXT("view")) == 0)
    {
        return bench_main(argc, argv, "majsimai-cpp", "view", ParseAsView);
    }
    if (BENCH_STRCMP(argv[4], BENCH_TEXT("model")) == 0)
    {
        return bench_main(argc, argv, "majsimai-cpp", "model", ParseAsModel);
    }
    return bench_main(argc, argv, "majsimai-cpp", "unknown", nullptr);
}
